1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = { premium: number } | { payout: number; remainingCap: number };
37	
38	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
39	
40	const PROCESSING_FEE = 5;
41	
42	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
43	
44	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
45	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
46	
47	/** The closed set of insurable item types, each with its base premium in gold. */
48	const BASE_PREMIUMS = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	} as const satisfies Record<string, number>;
56	
57	export type ItemType = keyof typeof BASE_PREMIUMS;
58	
59	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as ItemType];
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_BASE_PREMIUM = 60;
63	
64	/** Groups items by type; "alike" means same type, not same family. */
65	const groupByType = (items: Item[]): Item[][] => {
66	  const types = [...new Set(items.map((item) => item.type))];
67	  return types.map((type) => items.filter((item) => item.type === type));
68	};
69	
70	const COMPONENT_TYPES = new Set<string>(["rune", "moonstone"]);
71	
72	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
73	
74	/** Three alike components form a block, priced at a special base premium. */
75	const basePremiumOfGroup = (group: Item[]): number =>
76	  group.length === BLOCK_SIZE && group.every(isComponent)
77	    ? BLOCK_BASE_PREMIUM
78	    : sum(group.map(basePremiumOf));
79	
80	const totalBasePremium = (items: Item[]): number =>
81	  sum(groupByType(items).map(basePremiumOfGroup));
82	
83	const CURSE_SURCHARGE_RATE = 0.5;
84	
85	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
86	const HIGH_ENCHANTMENT_THRESHOLD = 5;
87	
88	const isCursed = (item: Item): boolean => item.cursed === true;
89	
90	const isHighlyEnchanted = (item: Item): boolean =>
91	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
92	
93	const itemSurchargeRate = (item: Item): number =>
94	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
95	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
96	
97	/**
98	 * Item-specific surcharges apply to the affected item's own base premium,
99	 * unlike policy-wide modifiers which apply to the policy's total base premium.
100	 */
101	const itemSurcharges = (items: Item[]): number =>
102	  sum(items.map((item) => basePremiumOf(item) * itemSurchargeRate(item)));
103	
104	/** Policy-wide modifiers apply to the policy's base premium, not to the item surcharges. */
105	const policyModifiers = (basePremium: number): number =>
106	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
107	
108	const quotePremium = (items: Item[]): number => {
109	  const basePremium = totalBasePremium(items);
110	  const premiumBeforeFee =
111	    basePremium + itemSurcharges(items) + policyModifiers(basePremium);
112	  return roundPremium(premiumBeforeFee + PROCESSING_FEE);
113	};
114	
115	const runStep = (step: Step): Result => {
116	  if (step.op === "quote") return { premium: quotePremium(step.items) };
117	  throw new Error(`Unsupported step: ${step.op}`);
118	};
119	
120	export const runScenario = (scenario: Scenario): { results: Result[] } => {
121	  return { results: scenario.steps.map(runStep) };
122	};
